			state = #mouse_state_move ;
			if(onDragStart)
			{
				onDragStart();
			}
		}
		if(state==#mouse_state_move)
		{
			view.move( evt.xScreen - xoff, evt.yScreen - yoff, true); // true - x,y are coordinates of the client area on the screen
			return true;
		}
		return false;
    }
      
    function onMouseUp(evt) 
    { 
	//	log("up:"+to_json_string(evt.mainButton)) ;
		var s = state ;
		state = #mouse_state_normal ;
    	root.capture(false);   
    	if(s == #mouse_state_move)
    	{
    		if(onDragEnd)
    			onDragEnd();
    	} 	
    	return s == #mouse_state_move ;
    }
